package main

import "fmt"

type Counter struct {
    value int
}

func (c *Counter) Add(n int) {
    c.value += n
}

func (c Counter) Value() int {
    return c.value
}

func main() {
    c := Counter{}
    c.Add(3)
    c.Add(4)
    fmt.Println(c.Value())
}
